export type Operation = keyof Arguments;
export type NativeRequest = {
  protocol: typeof PROTOCOL;
  request_id: string;
  operation: Operation;
  arguments: Arguments[Operation];
};
export type NativeResponse<O extends Operation = Operation> =
  | {
      protocol: typeof PROTOCOL;
      request_id: string;
      kind: "result";
      data: Results[O];
    }
  | {
      protocol: typeof PROTOCOL;
      request_id: string;
      kind: "error";
      error: Error;
    };
type Spec = string | { [key: string]: any };
const definitions = CONTRACT.definitions as Record<string, Spec>;
const operations = CONTRACT.operations as Record<
  string,
  { arguments: Spec; result: Spec }
>;
function matches(value: unknown, spec: Spec): boolean {
  if (typeof spec === "string")
    return spec.startsWith("?")
      ? value === null || matches(value, spec.slice(1))
      : matches(value, definitions[spec]);
  if (spec.one_of)
    return spec.one_of.some((item: Spec) => matches(value, item));
  if (spec.fields) {
    if (!value || typeof value !== "object" || Array.isArray(value))
      return false;
    const row = value as Record<string, unknown>;
    return (
      Object.keys(row).every((key) => Object.hasOwn(spec.fields, key)) &&
      Object.keys(spec.fields).every(
        (key) => Object.hasOwn(row, key) || spec.optional.includes(key),
      ) &&
      Object.entries(row).every(([key, item]) =>
        matches(item, spec.fields[key]),
      )
    );
  }
  if (spec.items)
    return (
      Array.isArray(value) &&
      value.length <= spec.max &&
      value.every((item) => matches(item, spec.items))
    );
  if (spec.type === "boolean")
    return (
      typeof value === "boolean" &&
      (!Object.hasOwn(spec, "const") || value === spec.const)
    );
  if (spec.type === "integer" || spec.type === "number")
    return (
      typeof value === "number" &&
      Number.isFinite(value) &&
      (spec.type !== "integer" || Number.isSafeInteger(value)) &&
      value >= spec.min &&
      value <= spec.max
    );
  if (
    typeof value !== "string" ||
    /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/u.test(
      value,
    )
  )
    return false;
  if (
    spec.max_bytes !== undefined &&
    new TextEncoder().encode(value).length > spec.max_bytes
  )
    return false;
  if (spec.enum && !spec.enum.includes(value)) return false;
  if (spec.format === "id") return /^[0-9a-f]{32}$/.test(value);
  if (spec.format === "digest") return /^[0-9a-f]{64}$/.test(value);
  if (spec.format === "decimal") return /^(0|[1-9][0-9]{0,18})$/.test(value);
  return true;
}
export function isNativeRequest(value: unknown): value is NativeRequest {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const row = value as Record<string, unknown>;
  return (
    Object.keys(row).length === 4 &&
    row.protocol === PROTOCOL &&
    matches(row.request_id, "id") &&
    typeof row.operation === "string" &&
    Object.hasOwn(operations, row.operation) &&
    matches(row.arguments, operations[row.operation].arguments)
  );
}
export function isNativeResponse<O extends Operation>(
  operation: O,
  value: unknown,
): value is NativeResponse<O> {
  if (
    !value ||
    typeof value !== "object" ||
    Array.isArray(value) ||
    !Object.hasOwn(operations, operation)
  )
    return false;
  const row = value as Record<string, unknown>;
  if (
    Object.keys(row).length !== 4 ||
    row.protocol !== PROTOCOL ||
    !matches(row.request_id, "id")
  )
    return false;
  if (
    new TextEncoder().encode(JSON.stringify(value)).length >
    BOUNDS.response_bytes
  )
    return false;
  return row.kind === "result"
    ? Object.hasOwn(row, "data") &&
        matches(row.data, operations[operation].result)
    : row.kind === "error" &&
        Object.hasOwn(row, "error") &&
        matches(row.error, "error");
}
